void FAlsRigVMFunction_DamperExactVector::Initialize()
{
	bInitialized = false;
}

FAlsRigVMFunction_DamperExactVector_Execute()
{
	DECLARE_SCOPE_HIERARCHICAL_COUNTER_RIGUNIT()

	if (!bInitialized)
	{
		bInitialized = true;
		Current = Target;
	}

	Current = UAlsMath::DamperExact(Current, Target, UE_REAL_TO_FLOAT(ExecuteContext.GetDeltaTime()), HalfLife);
}

inline float UAlsMath::DamperExactAlpha(const float DeltaTime, const float HalfLife)
{
	// https://theorangeduck.com/page/spring-roll-call#exactdamper

	return 1.0f - FMath::InvExpApprox(UE_LN2 / (HalfLife + UE_SMALL_NUMBER) * DeltaTime);
}

template <typename ValueType>
ValueType UAlsMath::DamperExact(const ValueType& Current, const ValueType& Target, const float DeltaTime, const float HalfLife)
{
	return FMath::Lerp(Current, Target, DamperExactAlpha(DeltaTime, HalfLife));
}

void FAnimNode_ControlRig::Initialize_AnyThread(const FAnimationInitializeContext& Context)
{
	DECLARE_SCOPE_HIERARCHICAL_COUNTER_FUNC()

	FAnimNode_ControlRigBase::Initialize_AnyThread(Context);

	if (ControlRig)
	{
		//Don't Inititialize the Control Rig here it may have the wrong VM on the CDO
		SetTargetInstance(ControlRig);
		ControlRig->RequestInit();
		bControlRigRequiresInitialization = true;
		LastBonesSerialNumberForCacheBones = 0;
	}

    "FAlsRigVMFunction_DamperExactVector::Execute",
    [
        Vector(target),
        F32(half_life),
        Vector(current),
        Bool(initialized),
    ],
) => {
    if !*initialized {
        *initialized = true;
        *current = *target;
    }
    let alpha = rig_damper_alpha(self.delta_seconds as f32, *half_life);
    *current += (*target - *current) * alpha as f64;
}

state.to_world = to_world;
state.calls.clear();
state.traces.clear();
let rebuild = state.runtime.as_ref().is_none_or(|runtime| runtime.definition != *definition);
if rebuild {
    state.runtime = Some(ControlRigRuntime {
        definition: definition.clone(),
        hierarchy: RigHierarchy::new(
            definition.bones.clone(),
            definition.translation_tolerance,
        )?,
        values: definition.program.initial_values.clone(),
        curves: definition
            .curves
            .iter()
            .filter_map(|(key, value)| value.map(|value| (key.clone().into(), value)))
            .collect(),
    });
}
